{"file_path":"/work/tests/test_spec.py","content":"import pytest

from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_none_counts_as_not_flagged():
    assert monitor_flag_rate([{"flagged": None}, {"flagged": True}]) == 0.5
    assert monitor_flag_rate([]) == 0.0


def test_pooled_rate_weights_transcripts():
    groups = {"a": [{"flagged": False}] * 3, "b": [{"flagged": True}], "c": []}
    assert pooled_flag_rate(groups) == 0.25
    assert pooled_flag_rate({"empty": []}) == 0.0


def test_trailing_window():
    assert flags_in_window([8, 4, 1], 2) == 5
    assert flags_in_window([8, 4, 1], 0) == 0
    assert flags_in_window([8, 4, 1], 5) == 13


def test_parse_comments_whitespace_and_flags():
    lines = ["", "   \n", "  # comment", " a , 3 , 1 ", "b, 4, 0", "c,5, "]
    assert parse_transcript_log(lines) == [
        {"id": "a", "day": 3, "flagged": True},
        {"id": "b", "day": 4, "flagged": False},
        {"id": "c", "day": 5, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["a,3", "a,1,0,1", "a,x,1"])
def test_parse_reports_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"line 4\b"):
        parse_transcript_log(["# header", "x,2,1", " ", bad_line])


def test_dedupe_keeps_last_duplicate_id_then_sorts():
    events = parse_transcript_log(["a,9,1", "z,2,1", "b,1,0", "a,2,0"])
    assert dedupe_transcripts(events) == [events[2], events[3], events[1]]


def test_daily_counts_fill_and_clip_range():
    events = parse_transcript_log(["a,1,1", "b,3,1", "c,3,1", "d,4,0", "e,6,1"])
    assert daily_flag_counts(events, 2, 5) == [0, 2, 0, 0]
    assert daily_flag_counts(events, 5, 2) == []


def test_summary_uses_calendar_window_and_nonempty_groups():
    groups = {"a": parse_transcript_log(["a,1,1", "b,5,0"]),
              "b": parse_transcript_log(["c,2,1"]), "empty": []}
    assert monitor_summary(groups, 3) == {"rate": 0.667, "recent": 0, "groups": 2}
    assert monitor_summary({}, 3) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_ranked_groups_skip_empty_and_break_ties_by_name():
    groups = {"z": [{"flagged": True}], "b": [{"flagged": None}],
              "a": [{"flagged": True}], "empty": []}
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_group_rates_include_empty_and_sort_keys():
    groups = {"z": [{"flagged": False}], "b": [], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("z", 0.0)]


@pytest.mark.parametrize("counts, expected", [([], 0), ([0, -1], 0), ([1, 0, 1, 2, -1, 1], 2)])
def test_streak_requires_consecutive_positive_days(counts, expected):
    assert longest_flag_streak(counts) == expected
